CREATE TABLE "ZipCode" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "code" TEXT NOT NULL,
    CONSTRAINT "ZipCode_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ZipCode_code_key" ON "ZipCode"("code");
CREATE UNIQUE INDEX "Publication_name_key" ON "Publication"("name");

CREATE TABLE "_PublicationToZipCode" (
    "A" TEXT NOT NULL,
    "B" INTEGER NOT NULL,
    CONSTRAINT "_PublicationToZipCode_AB_pkey" PRIMARY KEY ("A", "B")
);

CREATE INDEX "_PublicationToZipCode_B_index" ON "_PublicationToZipCode"("B");

ALTER TABLE "_PublicationToZipCode"
    ADD CONSTRAINT "_PublicationToZipCode_A_fkey"
    FOREIGN KEY ("A") REFERENCES "Publication"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "_PublicationToZipCode"
    ADD CONSTRAINT "_PublicationToZipCode_B_fkey"
    FOREIGN KEY ("B") REFERENCES "ZipCode"("id")
    ON DELETE CASCADE ON UPDATE CASCADE;
